// Real-time collaboration event types
interface CollaborationEvent {
  type: 'join' | 'leave' | 'operation' | 'cursor' | 'selection' | 'presence';
  documentId: string;
  userId: string;
  timestamp: number;
  data?: any;
}

interface DocumentOperation {
  type: 'insert' | 'delete' | 'retain';
  position: number;
  length?: number;
  content?: string;
  attributes?: Record<string, any>;
}

// Server-side event handler
const handleDocumentOperation = (ws: WebSocket, event: CollaborationEvent) => {
  const { documentId, userId, data } = event;

  // Apply operational transformation
  const result = applyOperation(documentId, data.operation);

  // Broadcast to all connected clients except sender
  broadcastToDocument(documentId, {
    type: 'operation',
    documentId,
    userId,
    data: result
  }, ws);
};


// React component for collaborative editing
import { useState, useEffect, useRef } from 'react';
import { useWebSocket } from '../hooks/useWebSocket';

const CollaborativeEditor = ({ documentId }: { documentId: string }) => {
  const [document, setDocument] = useState<DocumentState>();
  const [operations, setOperations] = useState<Operation[]>([]);
  const ws = useWebSocket();

  // Apply optimistic updates
  const handleLocalChange = (operation: Operation) => {
    setOperations(prev => [...prev, operation]);
    setDocument(prev => applyOperation(prev, operation));

    // Send to server
    ws.send('operation', {
      documentId,
      operation,
      timestamp: Date.now()
    });
  };

  // Handle remote operations
  useEffect(() => {
    const handleRemoteOperation = (event: CollaborationEvent) => {
      if (event.userId !== ws.userId) {
        setOperations(prev => {
          const filtered = prev.filter(op => 
            op.timestamp !== event.timestamp
          );
          return [...filtered, event.data.operation];
        });

        setDocument(prev => applyOperation(prev, event.data.operation));
      }
    };

    ws.subscribe('operation', handleRemoteOperation);
    return () => ws.unsubscribe('operation', handleRemoteOperation);
  }, [ws]);

  return (
    <Editor
      document={document}
      onChange={handleLocalChange}
      collaborators={getCollaborators(documentId)}
    />
  );
};


// Complete CRUD controller with validation and error handling
import { Request, Response } from 'express';
import { Task } from '../models/Task';
import { createApiResponse } from '../utils/apiResponse';
import { validateTask } from '../validation/taskValidator';

export class TaskController {
  async getAllTasks(req: Request, res: Response) {
    try {
      const { page = 1, limit = 10, status } = req.query;

      const tasks = await Task.findMany({
        where: status ? { status } : undefined,
        skip: (page - 1) * limit,
        take: parseInt(limit as string),
        orderBy: { createdAt: 'desc' }
      });

      const total = await Task.count({
        where: status ? { status } : undefined
      });

      res.json(createApiResponse(true, tasks, undefined, {
        pagination: {
          page: parseInt(page as string),
          limit: parseInt(limit as string),
          total,
          totalPages: Math.ceil(total / parseInt(limit as string))
        }
      }));
    } catch (error) {
      res.status(500).json(createApiResponse(false, undefined, {
        code: 'DATABASE_ERROR',
        message: 'Failed to fetch tasks'
      }));
    }
  }

  async createTask(req: Request, res: Response) {
    try {
      const validation = validateTask(req.body);
      if (!validation.isValid) {
        return res.status(400).json(createApiResponse(false, undefined, {
          code: 'VALIDATION_ERROR',
          message: validation.errors.join(', ')
        }));
      }

      const task = await Task.create({
        data: {
          ...req.body,
          userId: req.user.id,
          status: 'pending'
        }
      });

      res.status(201).json(createApiResponse(true, task));
    } catch (error) {
      res.status(500).json(createApiResponse(false, undefined, {
        code: 'CREATION_FAILED',
        message: 'Failed to create task'
      }));
    }
  }

  // ... updateTask, deleteTask methods with similar patterns
}


// React components for CRUD operations with state management
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Task } from '../types/task';

const TaskList = () => {
  const queryClient = useQueryClient();

  const { data: tasks, isLoading, error } = useQuery({
    queryKey: ['tasks'],
    queryFn: () => fetchTasks(),
    staleTime: 5 * 60 * 1000, // 5 minutes
  });

  const createMutation = useMutation({
    mutationFn: (newTask: Omit<Task, 'id'>) => createTask(newTask),
    onMutate: async (newTask) => {
      // Optimistic update
      queryClient.cancelQueries({ queryKey: ['tasks'] });
      const previousTasks = queryClient.getQueryData(['tasks']);

      queryClient.setQueryData(['tasks'], (old: Task[] = []) => 
        [newTask, ...old]
      );

      return { previousTasks };
    },
    onError: (error, newTask, context) => {
      // Rollback on error
      queryClient.setQueryData(['tasks'], context?.previousTasks);
    },
    onSettled: () => {
      // Refetch to ensure consistency
      queryClient.invalidateQueries({ queryKey: ['tasks'] });
    }
  });

  if (isLoading) return <TaskListSkeleton />;
  if (error) return <ErrorMessage error={error} />;

  return (
    <div>
      <TaskForm onSubmit={createMutation.mutate} />
      <div>
        {tasks?.map(task => (
          <TaskItem 
            key={task.id} 
            task={task}
            onUpdate={(updates) => updateTask(task.id, updates)}
            onDelete={() => deleteTask(task.id)}
          />
        ))}
      </div>
    </div>
  );
};

