// Optimized React component with performance considerations
import { memo, useMemo, useCallback, lazy, Suspense } from 'react';
import { useVirtualScrolling } from '../hooks/useVirtualScrolling';

// Lazy load heavy components
const HeavyChart = lazy(() => import('./HeavyChart'));

const OptimizedTaskList = ({ tasks }: { tasks: Task[] }) => {
  // Memoize expensive calculations
  const processedTasks = useMemo(() => {
    return tasks.map(task => ({
      ...task,
      formattedDate: new Date(task.createdAt).toLocaleDateString(),
      priorityColor: getPriorityColor(task.priority)
    }));
  }, [tasks]);

  // Optimize event handlers
  const handleTaskUpdate = useCallback((taskId: string, updates: Partial<Task>) => {
    updateTask(taskId, updates);
  }, []);

  // Virtual scrolling for large lists
  const {
    virtualItems,
    containerProps,
    scrollbarProps
  } = useVirtualScrolling({
    items: processedTasks,
    itemHeight: 60,
    overscan: 5
  });

  return (
    <div>
      <Suspense fallback={<ChartSkeleton />}>
        <HeavyChart data={tasks} />
      </Suspense>

      <div {...containerProps}>
        {virtualItems.map(({ item, index }) => (
          <TaskItem
            key={item.id}
            task={item}
            onUpdate={handleTaskUpdate}
            style={{ position: 'absolute', top: index * 60 }}
          />
        ))}
      </div>

      <div {...scrollbarProps} />
    </div>
  );
};

// Wrap with memo to prevent unnecessary re-renders
export default memo(OptimizedTaskList);
